import { test, expect } from '@playwright/test';

test.describe('Rate Limit Error Handling', () => {
  const formUrl = 'https://example.com/form';

  test.beforeEach(async ({ page }) => {
    await page.goto(formUrl);
  });

  test('should display rate limit error after multiple submissions', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: /submit/i });
    const inputField = page.getByLabel('Input Field');

    for (let i = 0; i < 5; i++) {
      await inputField.fill('Test input');
      await submitButton.click();
      await page.waitForTimeout(100); // Simulate a slight delay between submissions
    }

    const errorMessage = page.getByText(/rate limit exceeded/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should not show rate limit error on first submission', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: /submit/i });
    const inputField = page.getByLabel('Input Field');

    await inputField.fill('First submission');
    await submitButton.click();

    const errorMessage = page.getByText(/rate limit exceeded/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
